// @layer verification — pure Phase-7 safe-subset derivation for Milestone 4
// (Autogenerated route tests). Given a kernel's registered route metadata, it
// selects which routes are *safe* to auto-smoke (hit with a bare GET/HEAD and
// expect a non-error response) and records, for every route it declines, *why*
// it was skipped — so a later report can say "N routes not smoke-tested, and
// why" instead of silently dropping coverage. This mirrors the honest,
// tri-state accounting of Milestone 3.5's skip state.
//
// It is intentionally derivation only:
//   - Slice 4.1 (this file): pure metadata → plan, no I/O, no spawning, total
//     over any RouteEntry[], never throws. Exhaustively unit-tested, and NOT
//     yet wired into any gate or the orchestrator.
//   - Slice 4.2: execute the plan against a booted deno/node/binary app inside
//     the smoke gates (reusing production-smoke.ts's HTTP probe machinery), and
//     derive expectedStatus/content-type/body assertions beyond the default.
//   - Slice 4.3 (this file, now): example-driven parameterized routes +
//     `productionTest` route metadata. A route becomes a probe iff two orthogonal
//     gates pass — `safe` (or a safe method) UNLOCKS the method, and
//     `exampleRequest` SATISFIES the inputs (path params / required query /
//     required body). An unsatisfied gate leaves the route honestly skipped with
//     the first-unsatisfied-gate reason (no new reasons, no silent drops). The
//     resolved request (promoted method, substituted path, query string, JSON
//     body) is baked onto the RouteProbe so the gate stays dumb.
//   - Slice 4.4 (Phase 8): Deno/Node/binary route parity (consumes the
//     `deterministicBody` flag threaded through the probe now).
//
// It is a sibling of production-smoke.ts within the verification layer, so
// importing that module's shared route/status constants is an intra-layer
// import. RouteEntry/RouteSchema/sortRoutes come from core/types.ts (down, L1).
import {
  type RouteEntry,
  type RouteSchema,
  sortRoutes,
} from "../core/types.ts";
import {
  HEALTH_OK_STATUS,
  HEALTH_ROUTE,
  HTTP_GET,
  HTTP_HEAD,
  OPENAPI_ROUTE,
} from "./production-smoke.ts";

// --- Safe HTTP methods --------------------------------------------------------

// The only methods a bare, input-free probe may auto-hit; everything else is a
// mutating method and is skipped-with-reason. They are DEFINED in production-smoke.ts
// (the base module that also executes the probes — see the cycle note there) and
// re-exported here so the classifier, its tests, and existing consumers keep
// importing them from this module. No magic method strings.
export { HTTP_GET, HTTP_HEAD };

// --- Skip reasons -------------------------------------------------------------

// Why a registered route was deliberately *not* turned into a probe. Recorded
// verbatim on each SkippedRoute so a later report is honest about the gap.
export const SKIP_MUTATING_METHOD = "mutating method";
export const SKIP_REQUIRES_PATH_PARAM = "requires path parameter";
export const SKIP_REQUIRES_QUERY = "requires query parameter";
export const SKIP_REQUIRES_BODY = "requires request body";

// --- Plan shape ---------------------------------------------------------------

// A route the plan will auto-hit. It is the single carrier of the FULLY-RESOLVED
// request the gate then executes: `method` is the route's own method (a safe
// GET/HEAD, or a productionTest.safe-promoted mutating method — so it is a plain
// `string`, not just GET/HEAD, from Slice 4.3 on); `path` bakes in the
// encodeURIComponent-substituted path params and a deterministic (sorted-key)
// query string, so the gate still just does `new URL(probe.path, base)`;
// `expectedStatus` is productionTest.expectedStatus ?? the lowest declared 2xx
// (else HEALTH_OK_STATUS) and `expectsJson` is whether that expected-status
// response declares a JSON body schema — both from schema.responses. `requestBody`
// is present ONLY when the plan resolved a JSON body for a body-allowing method
// (a fixture-supplied POST/PUT/PATCH/DELETE body); GET/HEAD probes never carry one
// (fetch forbids a body on them). `deterministicBody` is threaded now for the
// Slice 4.4 parity pass. So the gate stays dumb: it just probes and compares.
export interface RouteProbe {
  method: string;
  path: string;
  expectedStatus: number;
  expectsJson: boolean;
  requestBody?: unknown;
  deterministicBody: boolean;
}

// A registered route the plan deliberately will not auto-hit, with the reason.
export interface SkippedRoute {
  method: string;
  path: string;
  reason: string;
}

export interface RouteSmokePlan {
  probes: RouteProbe[];
  skipped: SkippedRoute[];
}

// --- Classification helpers ---------------------------------------------------

// The platform's always-generate pair. Excluded from the per-route pass so
// they are never duplicated into probes nor mistakenly recorded as skipped.
// "Platform", not "framework": these are routes the kernel emits into every
// generated app, nothing to do with what library the app's own code uses.
const PLATFORM_ROUTES: ReadonlySet<string> = new Set([
  HEALTH_ROUTE,
  OPENAPI_ROUTE,
]);

// Whether a path is one of the platform's always-generate pair. Exported so the
// gate filters the plan's probes against the SAME set the derivation excludes,
// rather than re-deriving it — the platform pair is probed strictly by
// checkSmokeContract and must not be double-hit in the per-route pass.
export function isPlatformRoute(path: string): boolean {
  return PLATFORM_ROUTES.has(path);
}

// Every `:param` segment in a kernel route path, e.g. `/users/:id` → `id`. The global
// form is used both to enumerate a route's required params and to substitute
// them; a value with a `/` or space cannot break out of its segment because each
// substituted value is encodeURIComponent-encoded.
const PATH_PARAM_PATTERN = /:(\w+)/g;

function isSafeMethod(method: string): boolean {
  return method === HTTP_GET || method === HTTP_HEAD;
}

// Whether a method may carry a request body. GET/HEAD cannot (fetch throws on a
// GET/HEAD with a body), so a required-body GET/HEAD is a contradiction that stays
// skipped even with a body fixture (see gate (iv) in classifyRoute).
function methodAllowsBody(method: string): boolean {
  return method !== HTTP_GET && method !== HTTP_HEAD;
}

// The names a route requires as path parameters: every `:param` segment in the
// path PLUS every declared schema.params key (deduped). A route is only probeable
// when exampleRequest.pathParams covers ALL of them.
function requiredPathParams(route: RouteEntry): string[] {
  const names = new Set<string>();
  for (const match of route.path.matchAll(PATH_PARAM_PATTERN)) {
    if (match[1]) names.add(match[1]);
  }
  for (const key of Object.keys(route.schema?.params ?? {})) names.add(key);
  return [...names];
}

// The query keys a route marks required — each must be present in
// exampleRequest.query for the route to be probeable.
function requiredQueryKeys(schema: RouteSchema | undefined): string[] {
  const query = schema?.query;
  if (query === undefined) return [];
  return Object.entries(query)
    .filter(([, q]) => q.required === true)
    .map(([key]) => key);
}

function hasRequiredBody(schema: RouteSchema | undefined): boolean {
  return Boolean(schema?.body?.required?.length);
}

// Substitute encoded path-param values into a kernel route path. Returns null ("this
// fixture does not cover every `:param`") when any `:param` segment has no value —
// a total defense even though classifyRoute already gates coverage. Each value is
// encodeURIComponent-encoded so it stays within its segment.
function substitutePathParams(
  path: string,
  pathParams: Record<string, string> | undefined,
): string | null {
  let unsatisfied = false;
  const out = path.replace(PATH_PARAM_PATTERN, (match, name: string) => {
    const value = pathParams?.[name];
    if (value === undefined) {
      unsatisfied = true;
      return match;
    }
    return encodeURIComponent(value);
  });
  return unsatisfied ? null : out;
}

// Build the `?a=1&b=2` suffix from a query fixture, with keys SORTED and both keys
// and values encodeURIComponent-encoded, so the same fixture yields a
// byte-identical path regardless of key insertion order. Empty/absent → "".
function buildQueryString(query: Record<string, string> | undefined): string {
  if (query === undefined) return "";
  const keys = Object.keys(query).toSorted();
  if (keys.length === 0) return "";
  const pairs = keys.map(
    (key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key]!)}`,
  );
  return `?${pairs.join("&")}`;
}

// One route → either a fully-resolved probe or a skip with the first-unsatisfied
// gate's reason. Total, never throws. Two orthogonal gates decide whether the
// route is auto-hit, in fixed precedence (so the recorded reason is deterministic
// and no new skip-reason constants are needed):
//   (i)   METHOD — a safe GET/HEAD, OR productionTest.safe === true. This is the
//         ONLY thing that lets a mutating method through; an unmarked
//         POST/PUT/PATCH/DELETE is never auto-executed (SKIP_MUTATING_METHOD).
//   (ii)  PATH PARAMS — every `:param` segment / schema.params key is covered by
//         exampleRequest.pathParams (SKIP_REQUIRES_PATH_PARAM).
//   (iii) QUERY — every required query key is present in exampleRequest.query
//         (SKIP_REQUIRES_QUERY).
//   (iv)  BODY — a required body is supplied by exampleRequest.body AND the method
//         can carry one. A required-body GET/HEAD is a contradiction (fetch
//         forbids a GET/HEAD body), so it stays skipped even WITH a fixture
//         (SKIP_REQUIRES_BODY).
type Classification =
  | { kind: "probe"; probe: RouteProbe }
  | { kind: "skip"; reason: string };

function classifyRoute(route: RouteEntry): Classification {
  const test = route.schema?.productionTest;
  const method = route.method;

  // (i) Method: safe, or explicitly marked safe by the author.
  if (!isSafeMethod(method) && test?.safe !== true) {
    return { kind: "skip", reason: SKIP_MUTATING_METHOD };
  }

  // (ii) Path params: the fixture must cover every required name.
  const pathParams = test?.exampleRequest?.pathParams;
  if (
    requiredPathParams(route).some((name) => pathParams?.[name] === undefined)
  ) {
    return { kind: "skip", reason: SKIP_REQUIRES_PATH_PARAM };
  }

  // (iii) Required query: the fixture must supply every required key.
  const query = test?.exampleRequest?.query;
  if (
    requiredQueryKeys(route.schema).some((key) => query?.[key] === undefined)
  ) {
    return { kind: "skip", reason: SKIP_REQUIRES_QUERY };
  }

  // (iv) Required body: supplied AND sendable (not a GET/HEAD).
  if (hasRequiredBody(route.schema)) {
    const bodySupplied = test?.exampleRequest?.body !== undefined;
    if (!methodAllowsBody(method) || !bodySupplied) {
      return { kind: "skip", reason: SKIP_REQUIRES_BODY };
    }
  }

  // All gates satisfied → resolve the request onto the probe. The substitution
  // cannot fail here (gate (ii) proved coverage), but stay total: an unexpected
  // null degrades to an honest path-param skip rather than a bad probe.
  const substituted = substitutePathParams(route.path, pathParams);
  if (substituted === null) {
    return { kind: "skip", reason: SKIP_REQUIRES_PATH_PARAM };
  }

  const expectedStatus = test?.expectedStatus ??
    deriveExpectedStatus(route.schema);
  const probe: RouteProbe = {
    method,
    path: substituted + buildQueryString(query),
    expectedStatus,
    expectsJson: responseExpectsJson(route.schema, expectedStatus),
    deterministicBody: test?.deterministicBody ?? false,
  };
  // The body is sent only for a body-allowing method (fetch forbids a GET/HEAD
  // body); a fixture body on a GET/HEAD is simply not carried.
  const body = test?.exampleRequest?.body;
  if (body !== undefined && methodAllowsBody(method)) {
    probe.requestBody = body;
  }
  return { kind: "probe", probe };
}

// --- Per-route contract derivation --------------------------------------------

// The status a bare probe should expect: the LOWEST declared 2xx in
// schema.responses (so a route declaring only "201" expects 201), falling back to
// HEALTH_OK_STATUS when no 2xx is declared (or no/partial schema). Pure, total,
// never throws over any partial/missing schema; codepoint-deterministic (a numeric
// min, order-independent).
export function deriveExpectedStatus(schema: RouteSchema | undefined): number {
  const responses = schema?.responses;
  if (responses === undefined) return HEALTH_OK_STATUS;
  let lowest: number | undefined;
  for (const key of Object.keys(responses)) {
    const status = Number(key);
    if (!Number.isInteger(status)) continue;
    if (status < 200 || status >= 300) continue;
    if (lowest === undefined || status < lowest) lowest = status;
  }
  return lowest ?? HEALTH_OK_STATUS;
}

// Whether the response declared for `expectedStatus` carries a body schema — i.e.
// the route promises a JSON body, so the gate should assert the body parses as JSON
// and the content-type is sane. Total/never-throws: a missing status key or
// schema-less response is simply "not JSON".
function responseExpectsJson(
  schema: RouteSchema | undefined,
  expectedStatus: number,
): boolean {
  const response = schema?.responses?.[String(expectedStatus)];
  return response?.schema !== undefined;
}

// --- Plan derivation ----------------------------------------------------------

// Pure, total, never-throws: given the registered routes and whether the export
// emits OpenAPI, derive the conservative safe-subset smoke plan. Same inputs →
// byte-identical plan (both lists are deduped and (path, method)-sorted), so the
// result is machine-independent and safe to compare across targets in 4.4.
export function buildRouteSmokePlan(
  routes: readonly RouteEntry[],
  expectOpenApi: boolean,
): RouteSmokePlan {
  // The platform pair is probed strictly by checkSmokeContract, not this route
  // pass, so its expectedStatus/expectsJson are the plain health defaults (the gate
  // filters these out via isPlatformRoute before executing the plan).
  const probes: RouteProbe[] = [
    {
      method: HTTP_GET,
      path: HEALTH_ROUTE,
      expectedStatus: HEALTH_OK_STATUS,
      expectsJson: false,
      deterministicBody: false,
    },
  ];
  if (expectOpenApi) {
    probes.push({
      method: HTTP_GET,
      path: OPENAPI_ROUTE,
      expectedStatus: HEALTH_OK_STATUS,
      expectsJson: false,
      deterministicBody: false,
    });
  }

  const skipped: SkippedRoute[] = [];

  for (const route of routes) {
    // The always-generate pair is handled above; never duplicate or skip them.
    if (PLATFORM_ROUTES.has(route.path)) continue;

    const result = classifyRoute(route);
    if (result.kind === "skip") {
      // The SkippedRoute always records the ORIGINAL (unsubstituted) method/path,
      // so a `/users/:id` skip reads as the route the author wrote.
      skipped.push({
        method: route.method,
        path: route.path,
        reason: result.reason,
      });
      continue;
    }
    probes.push(result.probe);
  }

  return {
    probes: sortRoutes(dedupeProbes(probes)),
    skipped: sortRoutes(skipped),
  };
}

// Dedupe probes by (method, path) so a caller passing a duplicated route can't
// double it. First occurrence wins (a duplicate route resolves to the same derived
// expectedStatus/expectsJson, so which one survives is immaterial).
function dedupeProbes(probes: readonly RouteProbe[]): RouteProbe[] {
  const seen = new Set<string>();
  const out: RouteProbe[] = [];
  for (const probe of probes) {
    const key = `${probe.method} ${probe.path}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(probe);
  }
  return out;
}
